-- SQL: load 'Математика (тест 02)' into the question bank
-- Run in Supabase SQL Editor after 016_question_bank.sql and insert_math_01.sql

with new_test as (
  insert into question_bank_tests (code, profile_id, title, status)
  values ('test_math_generated_02', 'nish_math', 'Математика (тест 02)', 'draft')
  returning id
)
insert into question_bank_items (test_id, question_number, block_key, text_kk, text_ru, answer_format, choices, image_svg)
select id, v.question_number, 'main', v.text_kk, v.text_ru, 'abcd', v.choices::jsonb, v.image_svg
from new_test, (values
  (1, 'Ұзындығы 24м болатын сым ұзындықтары 3:4:5 қатынасындай болатын үш бөлікке бөлінді. Сымның ортаңғы бөлігін табыңыз.', 'Проволока длиной 24 м была разделена на три части, длины которых относятся как 3:4:5. Найдите среднюю по длине часть проволоки.', '[{"text": "6", "correct": false}, {"text": "8", "correct": true}, {"text": "10", "correct": false}, {"text": "12", "correct": false}]', NULL),
  (2, 'Кітап 240 беттен тұрады. Оқушы бірінші күні кітаптың 3/8 бөлігін, ал екінші күні 1/4 бөлігін оқыды. Қанша бет оқылмады?', 'Книга состоит из 240 страниц. Ученик прочитал в первый день 3/8 книги, а во второй день 1/4 книги. Сколько страниц осталось непрочитанными?', '[{"text": "90", "correct": true}, {"text": "100", "correct": false}, {"text": "80", "correct": false}, {"text": "75", "correct": false}]', NULL),
  (3, 'Есептеңіз: (-7/15)×(-10/7)×(-15/10) + (-11/20)×(-20/11) - 1/2', 'Вычислите: (-7/15)×(-10/7)×(-15/10) + (-11/20)×(-20/11) - 1/2', '[{"text": "-1/2", "correct": true}, {"text": "1/2", "correct": false}, {"text": "-1/4", "correct": false}, {"text": "0", "correct": false}]', NULL),
  (4, 'Екі жұмысшы бірге жұмыс істесе, тапсырманы 10 сағатта орындайды. Біріншісі жалғыз жұмыс істесе, екіншісіне қарағанда 5 сағатқа тезірек орындайды. Егер бірінші жұмысшы тапсырманы жалғыз өзі x сағатта орындай алса, дұрыс құрастырылған теңдеуді табыңыз.', 'Два рабочих, работая вместе, выполняют задание за 10 часов. Первый, работая один, выполнил бы задание на 5 часов быстрее второго. Если первый рабочий, работая один, может выполнить задание за x часов, найдите правильно составленное уравнение.', '[{"text": "x+5+x=1/10", "correct": false}, {"text": "1/x+1/(x+5)=1/10", "correct": true}, {"text": "1/x+1/(x+5)=10", "correct": false}, {"text": "x+5+x=10", "correct": false}]', NULL),
  (5, 'Пойыз 80км/сағ жылдамдықпен 5 сағ жүрді. Дәл сол қашықтықты 100км/сағ жылдамдықпен пойыз қанша сағат жүреді?', 'Поезд двигался со скоростью 80 км/ч в течение 5 часов. За какое время поезд преодолеет то же расстояние, если его скорость будет 100 км/ч?', '[{"text": "5", "correct": false}, {"text": "4", "correct": true}, {"text": "6", "correct": false}, {"text": "3", "correct": false}]', NULL),
  (6, 'Ұзындығы 24π см шеңбердің диаметрі қандай?', 'Какова длина диаметра окружности, длина которой равна 24π см?', '[{"text": "12см", "correct": false}, {"text": "24см", "correct": true}, {"text": "8см", "correct": false}, {"text": "48см", "correct": false}]', NULL),
  (7, 'Қатардың келесі мүшесін табыңыз: 6; 3; 2; 6/4; 6/5; ?', 'Найдите следующий член последовательности: 6; 3; 2; 6/4; 6/5; ?', '[{"text": "6/7", "correct": false}, {"text": "1", "correct": true}, {"text": "6/8", "correct": false}, {"text": "5/6", "correct": false}]', NULL),
  (8, 'Жазыңқы бұрыштың 5/12 бөлігін құрайтын бұрыштың градустық өлшемі қандай?', 'Какова градусная мера угла, если она составляет 5/12 развернутого угла?', '[{"text": "70", "correct": false}, {"text": "75", "correct": true}, {"text": "65", "correct": false}, {"text": "80", "correct": false}]', NULL),
  (9, 'Берілген сандар аралығына кіретін бүтін сандардың қосындысын табыңыз: [-9,5; 6 1/4]', 'Найдите сумму целых чисел, входящих в заданный числовой промежуток: [-9,5; 6 1/4]', '[{"text": "-20", "correct": false}, {"text": "-24", "correct": true}, {"text": "-28", "correct": false}, {"text": "-18", "correct": false}]', NULL),
  (10, 'ЕКОК (36;54;90)', 'НОК (36;54;90)', '[{"text": "360", "correct": false}, {"text": "450", "correct": false}, {"text": "540", "correct": true}, {"text": "270", "correct": false}]', NULL),
  (11, 'Есептеңіз: -5/6 - (3 1/4 - 1 5/12)', 'Вычислите: -5/6 - (3 1/4 - 1 5/12)', '[{"text": "-8/3", "correct": true}, {"text": "8/3", "correct": false}, {"text": "-5/3", "correct": false}, {"text": "-11/6", "correct": false}]', NULL),
  (12, 'Диаметрі 40 см болатын дөңгелек 30 рет айналса неше метрге жетеді? π=3,14', 'Если круг диаметром 40 см совершает 30 оборотов, какое расстояние (в метрах) он пройдёт? π=3,14', '[{"text": "37,68", "correct": true}, {"text": "3,768", "correct": false}, {"text": "376,8", "correct": false}, {"text": "18,84", "correct": false}]', NULL),
  (13, 'Боялған бөліктің ауданын табыңыз.

![](figs/q13.png)', 'Найдите площадь закрашенной части.

![](figs/q13.png)', '[{"text": "100", "correct": true}, {"text": "108", "correct": false}, {"text": "96", "correct": false}, {"text": "104", "correct": false}]', '<svg viewBox="0 0 280 240" xmlns="http://www.w3.org/2000/svg"><polygon points="20,20 240,20 240,100 160,180 20,180" fill="#d9d9d9" stroke="black" stroke-width="2"/><text x="4" y="104" font-size="16">9</text><text x="120" y="200" font-size="16">12</text><text x="245" y="145" font-size="14">4</text><text x="185" y="200" font-size="14">4</text></svg>'),
  (14, '4 пен x-тің қосындысын 5-ке көбейткенде -35-ке тең болады. x-ті табыңыз.', 'Сумма 4 и x, умноженная на 5, равна -35. Найдите x.', '[{"text": "-11", "correct": true}, {"text": "-3", "correct": false}, {"text": "-7", "correct": false}, {"text": "11", "correct": false}]', NULL),
  (15, 'Фигураның ауданын табыңыз.

![](figs/q15.png)', 'Найдите площадь фигуры.

![](figs/q15.png)', '[{"text": "126", "correct": false}, {"text": "102", "correct": true}, {"text": "98", "correct": false}, {"text": "110", "correct": false}]', '<svg viewBox="0 0 260 190" xmlns="http://www.w3.org/2000/svg"><polygon points="20,20 145,20 145,60 220,60 220,150 20,150" fill="#d9d9d9" stroke="black" stroke-width="2"/><text x="115" y="14" font-size="13">8</text><text x="4" y="90" font-size="13">9</text><text x="225" y="105" font-size="13">5</text><text x="175" y="55" font-size="11">4</text><text x="115" y="165" font-size="13">14</text></svg>'),
  (16, 'Хауызды екі құбырмен толтыруға болады. Екі құбыр бірге 15 сағатта толтырады. Екі құбыр бірге 6 сағатта хауыздың қандай бөлігін толтырады?', 'Бассейн можно наполнить двумя трубами. Обе трубы вместе наполняют бассейн за 15 часов. Какую часть бассейна заполнят обе трубы вместе за 6 часов?', '[{"text": "2/5", "correct": true}, {"text": "2/3", "correct": false}, {"text": "3/5", "correct": false}, {"text": "1/3", "correct": false}]', NULL),
  (17, 'Теңдеудің түбірлерінің қосындысын табыңыз: |x-8|/6 = 7,2/9', 'Найдите сумму корней уравнения: |x-8|/6 = 7,2/9', '[{"text": "16", "correct": true}, {"text": "-16", "correct": false}, {"text": "8", "correct": false}, {"text": "12", "correct": false}]', NULL),
  (18, '65-тің 20%-ын табыңыз.', 'Найдите 20% от 65.', '[{"text": "13", "correct": true}, {"text": "11", "correct": false}, {"text": "15", "correct": false}, {"text": "12,5", "correct": false}]', NULL),
  (19, '320-нің 3/8-ін табыңыз.', 'Найдите 3/8 от 320.', '[{"text": "100", "correct": false}, {"text": "120", "correct": true}, {"text": "140", "correct": false}, {"text": "110", "correct": false}]', NULL),
  (20, 'Ықшамдаңыз: 9x - 5(x-6)', 'Упростите: 9x - 5(x-6)', '[{"text": "4x+30", "correct": true}, {"text": "4x-30", "correct": false}, {"text": "14x-30", "correct": false}, {"text": "4x+11", "correct": false}]', NULL),
  (21, 'a/b=5/2 болса, b/(3a+2b) табыңыз.', 'Если a/b=5/2, найдите b/(3a+2b).', '[{"text": "2/19", "correct": true}, {"text": "5/19", "correct": false}, {"text": "2/11", "correct": false}, {"text": "1/2", "correct": false}]', NULL),
  (22, 'Кітаптың дүкендегі бағасы оның көтерме бағасынан 20%-ға қымбат. Егер кітаптың көтерме бағасы 2150 теңге болса, дүкендегі бағасы қандай?', 'Цена книги в магазине на 20% выше оптовой цены. Если оптовая цена книги составляет 2150 тенге, какова цена книги в магазине?', '[{"text": "2580", "correct": true}, {"text": "2500", "correct": false}, {"text": "2650", "correct": false}, {"text": "2450", "correct": false}]', NULL),
  (23, 'Үшбұрыштың периметрі 90см. Қабырға ұзындықтары 4, 5, 6 сандарына пропорционал. Ең үлкен және ең қысқа қабырғаларының айырмасын табыңыз.', 'Периметр треугольника равен 90 см. Длины его сторон пропорциональны числам 4, 5 и 6. Найдите разность между самой большой и самой маленькой сторонами.', '[{"text": "12", "correct": true}, {"text": "15", "correct": false}, {"text": "10", "correct": false}, {"text": "18", "correct": false}]', NULL),
  (24, '66 санын жай сандардың көбейтіндісі түрінде өрнектеңіз.', 'Разложите число 66 на множители, представляя его в виде произведения простых чисел.', '[{"text": "2×33", "correct": false}, {"text": "2×3×11", "correct": true}, {"text": "6×11", "correct": false}, {"text": "3×22", "correct": false}]', NULL),
  (25, '27 минут 1 сағаттың қанша процентін құрайды?', 'Сколько процентов составляет 27 минут от 1 часа?', '[{"text": "40%", "correct": false}, {"text": "45%", "correct": true}, {"text": "50%", "correct": false}, {"text": "35%", "correct": false}]', NULL),
  (26, '7/10 = 6/(5-a)', '7/10 = 6/(5-a)', '[{"text": "-25/7", "correct": true}, {"text": "25/7", "correct": false}, {"text": "-15/7", "correct": false}, {"text": "15/7", "correct": false}]', NULL),
  (27, 'Қабырғасы 4см болатын шаршылардан құралған фигураның периметрін табыңыз.

![](figs/q27.png)', 'Найдите периметр фигуры, составленной из квадратов со стороной 4 см.

![](figs/q27.png)', '[{"text": "48", "correct": false}, {"text": "56", "correct": true}, {"text": "64", "correct": false}, {"text": "40", "correct": false}]', '<svg viewBox="0 0 180 140" xmlns="http://www.w3.org/2000/svg"><rect x="20" y="90" width="30" height="30" fill="#d9d9d9" stroke="black"/><rect x="50" y="90" width="30" height="30" fill="#d9d9d9" stroke="black"/><rect x="50" y="60" width="30" height="30" fill="#d9d9d9" stroke="black"/><rect x="80" y="60" width="30" height="30" fill="#d9d9d9" stroke="black"/><rect x="80" y="30" width="30" height="30" fill="#d9d9d9" stroke="black"/><rect x="110" y="30" width="30" height="30" fill="#d9d9d9" stroke="black"/></svg>'),
  (28, 'x/6 = 4,2/1,4', 'x/6 = 4,2/1,4', '[{"text": "18", "correct": true}, {"text": "16", "correct": false}, {"text": "20", "correct": false}, {"text": "15", "correct": false}]', NULL),
  (29, 'Асанның жылдамдығы 80км/сағ. Ол 5 сағат жүргеннен соң оның артынан 120км/сағ жылдамдықпен Үсен шықты. Үсен Асанды қанша уақытта қуып жетеді?', 'Скорость Асана составляет 80 км/ч. Через 5 часов после его выезда Усен отправился следом со скоростью 120 км/ч. Через какое время Усен догонит Асана?', '[{"text": "10", "correct": true}, {"text": "8", "correct": false}, {"text": "12", "correct": false}, {"text": "9", "correct": false}]', NULL),
  (30, 'Қатардың келесі мүшесін табыңыз: 3; 6; 11; 18; 27; ?', 'Найдите следующий член последовательности: 3; 6; 11; 18; 27; ?', '[{"text": "36", "correct": false}, {"text": "38", "correct": true}, {"text": "40", "correct": false}, {"text": "34", "correct": false}]', NULL),
  (31, 'Сағат 7:20 көрсетіп тұр. Сағат тілдерінің арасындағы бұрыш неше градусты құрайды?', 'Часы показывают 7:20. Сколько градусов составляет угол между стрелками часов?', '[{"text": "100", "correct": true}, {"text": "95", "correct": false}, {"text": "105", "correct": false}, {"text": "110", "correct": false}]', NULL),
  (32, 'А нүктесінің координатасы (2,3). А нүктесінен координаталары (6,6) нүктесіне дейінгі қашықтықты табыңыз.', 'Координата точки А (2,3). Найдите расстояние от точки А до точки с координатами (6,6).', '[{"text": "4", "correct": false}, {"text": "5", "correct": true}, {"text": "6", "correct": false}, {"text": "7", "correct": false}]', NULL),
  (33, 'Теңдеудің неше түбірі бар? ||x|-8|=5', 'Сколько корней имеет уравнение? ||x|-8|=5', '[{"text": "2", "correct": false}, {"text": "3", "correct": false}, {"text": "4", "correct": true}, {"text": "5", "correct": false}]', NULL),
  (34, 'n санын x арқылы өрнектеңіз: (n+12)/4 = x-5', 'Выразите число n через число x: (n+12)/4 = x-5', '[{"text": "n=4x-32", "correct": true}, {"text": "n=4x+32", "correct": false}, {"text": "n=4x-8", "correct": false}, {"text": "n=0,25x-1,25", "correct": false}]', NULL),
  (35, 'Тіктөртбұрыштың ұзындығының еніне қатынасы 9:4. Ұзындығы енінен 25 см-ге артық. Тіктөртбұрыштың периметрін табыңыз.', 'Отношение длины к ширине прямоугольника как 9:4. Длина на 25 см больше, чем ширина. Найдите периметр прямоугольника.', '[{"text": "120", "correct": false}, {"text": "130", "correct": true}, {"text": "140", "correct": false}, {"text": "110", "correct": false}]', NULL),
  (36, 'Екі жұмысшы бірге орды 10 сағатта қазады. Біріншісі жалғыз қазса, екіншісіне қарағанда 5 сағатқа тезірек орындайды. Егер бірінші жұмысшы жалғыз x сағатта орындай алса, дұрыс құрастырылған теңдеуді табыңыз.', 'Два рабочих вместе выкапывают траншею за 10 часов. Первый, работая один, выполнил бы задание на 5 часов быстрее второго. Если первый рабочий, работая один, может выполнить задание за x часов, найдите правильно составленное уравнение.', '[{"text": "1/x+1/(x+5)=1/10", "correct": true}, {"text": "x+5+x=1/10", "correct": false}, {"text": "1/x+1/(x+5)=10", "correct": false}, {"text": "x-5+x=10", "correct": false}]', NULL),
  (37, 'Ықшамдаңыз: 6(3x-2) - 4(2x-5)', 'Упростите: 6(3x-2) - 4(2x-5)', '[{"text": "10x+8", "correct": true}, {"text": "10x-8", "correct": false}, {"text": "10x+32", "correct": false}, {"text": "26x+8", "correct": false}]', NULL),
  (38, 'Тауардың бағасы алдымен 20%-ға көтерілді, содан кейін жаңа бағадан 25%-ға жеңілдік жасалды. Бастапқы баға 400 теңге болса, соңғы баға қандай?', 'Цена товара сначала была повышена на 20%, а затем на новую цену сделали скидку 25%. Если начальная цена 400 тенге, какова конечная цена?', '[{"text": "360", "correct": true}, {"text": "400", "correct": false}, {"text": "380", "correct": false}, {"text": "340", "correct": false}]', NULL),
  (39, '10 жұмысшы қоршауды 18 күнде тұрғызады. 15 жұмысшы дәл сондай қоршауды неше күнде тұрғызады?', '10 рабочих строят забор за 18 дней. За сколько дней 15 рабочих построят такой же забор?', '[{"text": "15", "correct": false}, {"text": "12", "correct": true}, {"text": "10", "correct": false}, {"text": "20", "correct": false}]', NULL),
  (40, '33 минут 1 сағаттың қандай бөлігін құрайды?', 'Какую часть часа составляют 33 минуты?', '[{"text": "11/20", "correct": true}, {"text": "3/5", "correct": false}, {"text": "9/20", "correct": false}, {"text": "7/12", "correct": false}]', NULL)
) as v(question_number, text_kk, text_ru, choices, image_svg);